def get_config_dir():
    """Return the directory where refresh config files are stored

    This directory is determined by the OS_REFRESH_CONFIG_DIR environment
    variable. If that variable is not set, the default base directory is
    returned.
    """
    env_config_dir = os.environ.get('OS_REFRESH_CONFIG_DIR')
    if env_config_dir:
        return env_config_dir
    else:
        return default_base_dir()


def get_config_file():
    """Return the path to the refresh config file

    This file is determined by the OS_REFRESH_CONFIG_FILE environment
    variable. If that variable is not set, the default base directory is
    returned.
    """
    env_config_file = os.environ.get('OS_REFRESH_CONFIG_FILE')
    if env_config_file:
        return env_config_file
    else:
        return os.path.join(get_config_dir(), 'refresh_config')


def get_config_file_path(config_file):
    """Return the full path to the refresh config file

    This file is determined by the OS_REFRESH_CONFIG_FILE environment
    variable. If that variable is not set, the default base directory is
    returned.
    """
    return os.path.join(get_config_dir(), config_file)


def get_config_file_dir(config_file):
    """Return the directory where the refresh config file is stored

    This directory is determined by the OS_REFRESH_CONFIG_DIR environment
    variable. If that variable is not set, the default base directory is
    returned.
    """
    return os.path.dirname(get_config_file_path(config_file))


